package dev.y.works.iconescatolicosonline.service.carrinho;
import dev.y.works.iconescatolicosonline.domain.catalogo.*; import dev.y.works.iconescatolicosonline.domain.carrinho.ItemCarrinho; import dev.y.works.iconescatolicosonline.domain.usuario.*; import dev.y.works.iconescatolicosonline.dto.carrinho.*; import dev.y.works.iconescatolicosonline.dto.encomenda.PersonalizacaoRequest; import dev.y.works.iconescatolicosonline.exception.RecursoNaoEncontradoException; import dev.y.works.iconescatolicosonline.repository.carrinho.ItemCarrinhoRepository; import dev.y.works.iconescatolicosonline.repository.catalogo.ModeloIconeRepository; import dev.y.works.iconescatolicosonline.repository.usuario.ClienteRepository; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.math.BigDecimal; import java.util.Optional; import static org.assertj.core.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class CarrinhoServiceTests {
 @Mock ItemCarrinhoRepository repository;@Mock ClienteRepository clienteRepository;@Mock ModeloIconeRepository modeloRepository;CarrinhoService service;Cliente cliente;ModeloIcone modelo;
 @BeforeEach void setup(){service=new CarrinhoService(repository,clienteRepository,modeloRepository);Usuario usuario=new Usuario();usuario.setEmail("cliente@teste.com");cliente=new Cliente();cliente.setId(1L);cliente.setUsuario(usuario);modelo=new ModeloIcone();modelo.setId(2L);modelo.setNome("São José");modelo.setPrecoBase(new BigDecimal("300.00"));}
 @Test void deveAdicionarItemAoCarrinhoDoClienteAutenticado(){when(clienteRepository.findByUsuario_EmailIgnoreCase("cliente@teste.com")).thenReturn(Optional.of(cliente));when(modeloRepository.findByIdAndAtivoTrue(2L)).thenReturn(Optional.of(modelo));when(repository.save(any())).thenAnswer(i->{ItemCarrinho item=i.getArgument(0);item.setId(10L);return item;});var resposta=service.adicionar("cliente@teste.com",new AdicionarItemCarrinhoRequest(2L,2,new PersonalizacaoRequest(TamanhoIcone.MEDIO,null,null,null,null)));assertThat(resposta.id()).isEqualTo(10L);assertThat(resposta.quantidade()).isEqualTo(2);verify(repository).save(any());}
 @Test void deveImpedirRemocaoDeItemDeOutroCliente(){when(repository.findByIdAndCliente_Usuario_EmailIgnoreCase(99L,"cliente@teste.com")).thenReturn(Optional.empty());assertThatThrownBy(()->service.remover("cliente@teste.com",99L)).isInstanceOf(RecursoNaoEncontradoException.class);verify(repository,never()).delete(any());}
}
